<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';
use School\Core\SchoolAuth;
use School\Core\SchoolDatabase;
SchoolAuth::requireLogin();$user=SchoolAuth::user();$role=school_current_role($user);if(!SchoolAuth::hasPermission('students.view')&&!SchoolAuth::hasPermission('students.manage')&&!SchoolAuth::hasPermission('portal.child')&&!SchoolAuth::hasPermission('portal.self')){http_response_code(403);exit('Document access is not permitted.');}$documentId=(int)($_GET['id']??0);$pdo=SchoolDatabase::connection();$q=$pdo->prepare("SELECT d.*,en.class_group_id,en.academic_year_id FROM school_student_documents d LEFT JOIN enrollments en ON en.student_id=d.student_id AND en.status='active' WHERE d.id=:id AND d.archived_at IS NULL ORDER BY en.academic_year_id DESC LIMIT 1");$q->execute(['id'=>$documentId]);$document=$q->fetch();if(!$document){http_response_code(404);exit('Document not found.');}
if(in_array($role,['parent_guardian','student'],true)){$allowed=$document['category']==='previous_report'&&($role==='parent_guardian'?SchoolAuth::can('portal.child',['student_id'=>(int)$document['student_id']]):SchoolAuth::can('portal.self',['student_id'=>(int)$document['student_id']]));}else{$allowed=SchoolAuth::hasPermission('students.manage');}
if(!$allowed){http_response_code(403);exit('Document access is not permitted.');}
$key=(string)$document['storage_key'];if(!preg_match('/^[a-f0-9]{64}$/',$key)){http_response_code(404);exit('Document not found.');}$root=realpath(dirname(__DIR__,2).'/storage/private/student-documents');$path=realpath(($root?:'').'/'.$key);if(!$root||!$path||!str_starts_with($path,$root.DIRECTORY_SEPARATOR)||!is_file($path)){http_response_code(404);exit('Document not found.');}if(!hash_equals((string)$document['sha256'],(string)hash_file('sha256',$path))){http_response_code(500);exit('The stored document failed its integrity check.');}
$safeName=str_replace(["\r","\n",'"'],['','',''],$document['original_name']);header('Content-Type: '.$document['mime_type']);header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="document"; filename*=UTF-8\'\''.rawurlencode($safeName));header('Cache-Control: private, no-store, max-age=0');header('X-Content-Type-Options: nosniff');readfile($path);
